// ===== Check Caller & Build SMS =====
// Runs only for missed calls (the IF node before this filters answered calls).
// Returns [] to stop quietly when we should NOT text the caller.

const j = $input.first().json;
const b = j.body || {};
const onlyDigits = (s) => String(s || '').replace(/\D/g, '');

// 0) Shared secret in the URL (?key=...). Without it anyone who finds this URL
//    could make you pay to text any number they like.
const expectedKey = String(j.webhookKey || '');
if (!expectedKey || /^CHANGE_ME/i.test(expectedKey) || expectedKey.length < 12) {
  throw new Error('Config (Calls): set webhookKey to a long random string (12+ chars) and add ?key=... to the Twilio action URL.');
}
if (String((j.query || {}).key || '') !== expectedKey) {
  return [];
}

const from = String(b.From || b.Caller || '').trim();

// 1) Withheld / anonymous / malformed numbers cannot be texted.
// Twilio shows hidden caller IDs as keypad-spelled words: ANONYMOUS, RESTRICTED, BLOCKED, UNKNOWN, UNAVAILABLE.
const HIDDEN = ['+266696687', '+7378742883', '+2562533', '+8656696', '+86282452253'];
if (!/^\+[1-9]\d{7,14}$/.test(from) || HIDDEN.includes(from)) {
  return [];
}

// 2) Optional: only text numbers with these prefixes (e.g. "+447" = UK mobiles).
const prefixes = String(j.smsOnlyToPrefixes || '')
  .split(',').map((s) => s.trim()).filter(Boolean);
if (prefixes.length && !prefixes.some((p) => from.startsWith(p))) {
  return [];
}

// 3) Never text our own numbers (stops loops if staff call the line).
const own = [j.twilioFrom, j.whatsappNumber].map(onlyDigits).filter(Boolean);
if (own.includes(onlyDigits(from))) {
  return [];
}

// 4) Cooldown: a caller who rings 3 times in a row gets ONE text, not three.
const store = $getWorkflowStaticData('global');
store.sms = store.sms || {};
store.calls = store.calls || {};
const now = Date.now();
const key = onlyDigits(from);
const cooldownMs = (Number(j.smsCooldownMinutes) || 30) * 60 * 1000;

// housekeeping: forget records older than 7 days
const weekMs = 7 * 24 * 60 * 60 * 1000;
for (const bucket of [store.sms, store.calls]) {
  for (const k of Object.keys(bucket)) {
    if (now - bucket[k] > weekMs) delete bucket[k];
  }
}

store.lastCallRun = now; // top-level write guarantees n8n saves the static data
store.calls[key] = now; // lets the WhatsApp flow tag this lead as "missed call"

if (store.sms[key] && now - store.sms[key] < cooldownMs) {
  return [];
}
store.sms[key] = now;

// 5) Build the SMS with a click-to-WhatsApp link.
const waDigits = onlyDigits(j.whatsappNumber);
if (!waDigits) {
  throw new Error('Config (Calls): whatsappNumber is empty. Put your WhatsApp Business number there.');
}
const prefill = j.whatsappPrefill || 'Hi, I just called you';
const link = 'https://wa.me/' + waDigits + '?text=' + encodeURIComponent(prefill);
const smsText =
  (j.businessName || 'We') + ': sorry we missed your call! ' +
  'Book a callback or an engineer visit on WhatsApp in under a minute: ' + link;

return [{
  json: {
    to: from,
    twilioFrom: j.twilioFrom,
    smsText,
    link,
    callSid: b.CallSid || '',
    dialStatus: b.DialCallStatus || '',
  },
}];

// ===== Conversation Engine =====
// Deterministic state machine - no AI. Code decides every step.
// One WhatsApp message in  ->  one WhatsApp reply out (+ a booking when finished).
// Conversation state lives in workflow static data, keyed by phone number.
// NOTE: static data only persists when the workflow is ACTIVE (not in manual test runs).

const item = $input.first().json;
const onlyDigits = (s) => String(s || '').replace(/\D/g, '');
const isPlaceholder = (s) => !s || /^(YOUR_|REPLACE|PASTE)/i.test(String(s));

const cfg = {
  businessName: item.businessName || 'Our team',
  timezone: item.timezone || 'Europe/London',
  workDays: String(item.workDays || '1,2,3,4,5').split(',')
    .map((s) => parseInt(s.trim(), 10)).filter((n) => n >= 1 && n <= 7),
  graphVersion: item.graphVersion || 'v25.0',
  phoneNumberId: isPlaceholder(item.phoneNumberId) ? '' : String(item.phoneNumberId),
  ownerMobile: item.ownerMobile || '',
  twilioFrom: item.twilioFrom || '',
  calendarId: item.calendarId || '',
  sessionHours: Number(item.sessionHours) || 6,
};
if (!cfg.workDays.length) cfg.workDays = [1, 2, 3, 4, 5];

const OPEN_HOUR = 8;           // callbacks handled from 08:00...
const CLOSE_HOUR = 17;         // ...until 17:30
const WINDOWS = [
  { id: 'am',  title: 'Morning 8-12',   start: 8,  end: 12 },
  { id: 'pm',  title: 'Afternoon 12-4', start: 12, end: 16 },
  { id: 'eve', title: 'Evening 4-6',    start: 16, end: 18 },
];
const ISSUES = [
  { id: 'no_heating',   title: 'No heating' },
  { id: 'no_hot_water', title: 'No hot water' },
  { id: 'boiler_fault', title: 'Boiler fault / error' },
  { id: 'leak',         title: 'Leak or dripping' },
  { id: 'aircon',       title: 'Air con not working' },
  { id: 'service',      title: 'Service / maintenance' },
  { id: 'gas',          title: 'I can smell gas', description: 'Emergency - read this first' },
  { id: 'other',        title: 'Something else' },
];
const CHOICES = [
  { id: 'cb',    title: 'Request a callback' },
  { id: 'visit', title: 'Book a visit' },
];

// ---------- read the inbound payload (WhatsApp Trigger OR a raw Meta webhook) ----------
function getValue(j) {
  if (Array.isArray(j.messages) || Array.isArray(j.statuses)) return j;
  const viaBody = j.body && j.body.entry && j.body.entry[0] && j.body.entry[0].changes
    && j.body.entry[0].changes[0] && j.body.entry[0].changes[0].value;
  if (viaBody) return viaBody;
  const viaEntry = j.entry && j.entry[0] && j.entry[0].changes
    && j.entry[0].changes[0] && j.entry[0].changes[0].value;
  if (viaEntry) return viaEntry;
  if (j.value) return j.value;
  return {};
}
const value = getValue(item);
const messages = Array.isArray(value.messages) ? value.messages : [];
if (!messages.length) return []; // delivery/read receipts etc. - nothing to answer

const phoneNumberId = cfg.phoneNumberId || (value.metadata && value.metadata.phone_number_id) || '';
if (!phoneNumberId) {
  throw new Error('No phone_number_id found. Set phoneNumberId in "Config (WhatsApp)".');
}
const profileName = (value.contacts && value.contacts[0] && value.contacts[0].profile
  && value.contacts[0].profile.name) || '';

// ---------- state ----------
const store = $getWorkflowStaticData('global');
store.sessions = store.sessions || {};
store.seen = store.seen || [];
store.calls = store.calls || {};
const nowMs = Date.now();
const now = DateTime.now().setZone(cfg.timezone);

// housekeeping: drop sessions idle for 7+ days
for (const k of Object.keys(store.sessions)) {
  if (nowMs - (store.sessions[k].updated || 0) > 7 * 24 * 60 * 60 * 1000) delete store.sessions[k];
}

// ---------- WhatsApp payload builders ----------
const base = (to) => ({ messaging_product: 'whatsapp', recipient_type: 'individual', to });
const text = (to, body) => ({ ...base(to), type: 'text', text: { preview_url: false, body } });
const buttons = (to, body, opts) => ({
  ...base(to), type: 'interactive',
  interactive: {
    type: 'button',
    body: { text: body },
    action: { buttons: opts.map((o) => ({ type: 'reply', reply: { id: o.id, title: o.title } })) },
  },
});
const list = (to, body, buttonText, sectionTitle, rows) => ({
  ...base(to), type: 'interactive',
  interactive: {
    type: 'list',
    body: { text: body },
    action: {
      button: buttonText,
      sections: [{
        title: sectionTitle,
        rows: rows.map((r) => (r.description
          ? { id: r.id, title: r.title, description: r.description }
          : { id: r.id, title: r.title })),
      }],
    },
  },
});
const numbered = (opts) => opts.map((o, i) => (i + 1) + '. ' + o.title).join('\n');

// ---------- helpers ----------
function readInput(msg) {
  if (msg.type === 'text') {
    return { kind: 'text', id: '', text: String((msg.text && msg.text.body) || '').trim() };
  }
  if (msg.type === 'interactive' && msg.interactive) {
    const r = msg.interactive.list_reply || msg.interactive.button_reply;
    if (r) return { kind: 'choice', id: String(r.id || ''), text: String(r.title || '') };
  }
  if (msg.type === 'button' && msg.button) {
    return { kind: 'text', id: '', text: String(msg.button.text || '').trim() };
  }
  return { kind: 'other', id: '', text: '' }; // image, voice note, sticker, location...
}

// match a tap (id), a typed number ("2") or typed words ("no hot water")
function pick(input, opts) {
  if (input.kind === 'choice') return opts.find((o) => o.id === input.id) || null;
  if (input.kind !== 'text') return null;
  const t = input.text.toLowerCase().trim();
  if (!t) return null;
  if (/^\d{1,2}$/.test(t)) return opts[parseInt(t, 10) - 1] || null;
  return opts.find((o) => o.title.toLowerCase() === t)
    || opts.find((o) => t.length >= 4 && o.title.toLowerCase().includes(t))
    || null;
}

function tidyPostcode(raw) {
  const m = String(raw || '').toUpperCase().replace(/[^A-Z0-9]/g, '')
    .match(/^([A-Z]{1,2}\d[A-Z\d]?)(\d[A-Z]{2})$/);
  return m ? m[1] + ' ' + m[2] : null;
}

function nextWorkingDays(from, count) {
  const out = [];
  let d = from.startOf('day');
  for (let guard = 0; out.length < count && guard < 21; guard++) {
    d = d.plus({ days: 1 });
    if (cfg.workDays.includes(d.weekday)) {
      out.push({ id: d.toFormat('yyyy-LL-dd'), title: d.toFormat('ccc d LLL') });
    }
  }
  return out;
}

function callbackSlot(n) {
  const open = n.set({ hour: OPEN_HOUR, minute: 0, second: 0, millisecond: 0 });
  const close = n.set({ hour: CLOSE_HOUR, minute: 30, second: 0, millisecond: 0 });
  const workingToday = cfg.workDays.includes(n.weekday);
  let start; let label;
  if (workingToday && n >= open && n <= close) {
    const plus = n.plus({ minutes: 15 });
    start = plus.set({ second: 0, millisecond: 0 }).plus({ minutes: (5 - (plus.minute % 5)) % 5 });
    label = 'within the next 30 minutes';
  } else if (workingToday && n < open) {
    start = n.set({ hour: OPEN_HOUR, minute: 30, second: 0, millisecond: 0 });
    label = 'first thing this morning (from 8:30)';
  } else {
    const day = nextWorkingDays(n, 1)[0];
    start = DateTime.fromFormat(day.id, 'yyyy-LL-dd', { zone: cfg.timezone })
      .set({ hour: OPEN_HOUR, minute: 30 });
    label = 'first thing on ' + day.title + ' (from 8:30)';
  }
  return { start, end: start.plus({ minutes: 20 }), label };
}

const iso = (dt) => dt.toISO({ suppressMilliseconds: true });
const clip = (s, n) => (String(s).length > n ? String(s).slice(0, n - 1) + '...' : String(s));
const newRef = () => 'HV-' + Math.random().toString(36).slice(2, 7).toUpperCase().padEnd(5, '0');

function finish(s, phoneKey) {
  const d = s.data;
  const phone = '+' + phoneKey;
  let start; let end; let slotLabel; let kind;
  if (d.choice === 'visit') {
    const w = WINDOWS.find((x) => x.id === d.window);
    const day = DateTime.fromFormat(d.day, 'yyyy-LL-dd', { zone: cfg.timezone });
    start = day.set({ hour: w.start });
    end = day.set({ hour: w.end });
    slotLabel = d.dayLabel + ', ' + w.title;
    kind = 'VISIT';
  } else {
    const cb = callbackSlot(now);
    start = cb.start; end = cb.end; slotLabel = cb.label;
    kind = 'CALLBACK';
  }
  const lastCall = store.calls[phoneKey];
  const source = lastCall && nowMs - lastCall < 24 * 60 * 60 * 1000 ? 'Missed call' : 'Direct WhatsApp';
  const lines = [
    'Ref: ' + s.ref,
    'Type: ' + kind,
    'Name: ' + d.name,
    'Phone / WhatsApp: ' + phone,
    'Address: ' + d.address + ', ' + d.postcode,
    'Issue: ' + d.issueTitle,
    'Details: ' + d.details,
    'When: ' + slotLabel,
    'Source: ' + source,
  ];
  return {
    ref: s.ref,
    type: kind.toLowerCase(),
    name: d.name,
    phone,
    postcode: d.postcode,
    address: d.address,
    issue: d.issueTitle,
    details: d.details,
    slotLabel,
    source,
    startISO: iso(start),
    endISO: iso(end),
    summary: (kind === 'VISIT' ? 'VISIT REQUEST: ' : 'CALLBACK: ') + d.name + ' - ' + d.issueTitle + ' (' + d.postcode + ')',
    description: lines.join('\\n') + '\\n\\nStatus: NOT YET CONFIRMED with customer.',
    location: d.address + ', ' + d.postcode,
    ownerSms: clip('NEW ' + kind + ' ' + s.ref + '\\n' + d.name + ' ' + phone + '\\n' + d.address + ', ' + d.postcode
      + '\\n' + d.issueTitle + ': ' + clip(d.details, 160) + '\\nWhen: ' + slotLabel + '\\nSource: ' + source, 600),
  };
}

// ---------- the state machine ----------
function handle(msg) {
  const to = String(msg.from || '');
  const key = onlyDigits(to);
  if (!key) return null;
  const input = readInput(msg);
  const lower = input.text.toLowerCase();

  let s = store.sessions[key];
  const expired = s && nowMs - (s.updated || 0) > cfg.sessionHours * 60 * 60 * 1000;
  const restart = input.kind === 'text' && /^(menu|restart|start|start over|new|reset)$/.test(lower);
  let reply; let booking = null;

  const askIssue = (intro) => list(to,
    intro + '\n\nWhat do you need help with? Tap *Choose issue* below, or reply with a number:\n' + numbered(ISSUES),
    'Choose issue', 'How can we help?', ISSUES);

  if (!s || expired || restart) {
    const lastCall = store.calls[key];
    const fromCall = lastCall && nowMs - lastCall < 24 * 60 * 60 * 1000;
    s = { step: 'issue', data: {}, retries: 0, ref: newRef(), updated: nowMs };
    store.sessions[key] = s;
    const hello = 'Hi' + (profileName ? ' ' + clip(profileName.split(' ')[0], 30) : '') + ', thanks for contacting ' + cfg.businessName + '.';
    reply = askIssue(hello + (fromCall ? ' Sorry we missed your call - let\'s get you sorted right now.' : ' Let\'s get you sorted.'));
    return { to, reply, booking, step: s.step };
  }

  switch (s.step) {
    case 'issue': {
      let opt = pick(input, ISSUES);
      if (input.kind === 'text' && /\bgas\b/.test(lower)) opt = ISSUES.find((o) => o.id === 'gas'); // safety first
      if (!opt) { reply = askIssue('Sorry, I didn\'t catch that.'); break; }
      if (opt.id === 'gas') {
        delete store.sessions[key];
        reply = text(to, 'IMPORTANT - if you can smell gas:\n'
          + '1. Do not use light switches, flames or anything electrical.\n'
          + '2. Open doors and windows and leave the property.\n'
          + '3. Call the National Gas Emergency Service FREE on 0800 111 999 (24 hours).\n\n'
          + 'Once you are safe and the supply has been checked, reply MENU and we will book an engineer for you.');
        return { to, reply, booking, step: 'gas' };
      }
      s.data.issue = opt.id; s.data.issueTitle = opt.title;
      s.step = 'name'; s.retries = 0;
      reply = text(to, 'Got it - ' + opt.title.toLowerCase() + '.\n\nWhat is your full name?');
      break;
    }
    case 'name': {
      if (input.kind !== 'text' || input.text.length < 2 || input.text.length > 80) {
        reply = text(to, 'Please type your full name so our engineer knows who to ask for.'); break;
      }
      s.data.name = input.text;
      s.step = 'postcode'; s.retries = 0;
      reply = text(to, 'Thanks ' + clip(input.text.split(' ')[0], 30) + '. What is your postcode?');
      break;
    }
    case 'postcode': {
      const pc = input.kind === 'text' ? tidyPostcode(input.text) : null;
      if (!pc) {
        s.retries = (s.retries || 0) + 1;
        if (input.kind !== 'text' || s.retries < 2 || input.text.length < 3) {
          reply = text(to, 'That doesn\'t look like a UK postcode. Please send it like this: M1 4BT'); break;
        }
        s.data.postcode = clip(input.text.toUpperCase(), 12); // accept after 2 tries, a human will check it
      } else {
        s.data.postcode = pc;
      }
      s.step = 'address'; s.retries = 0;
      reply = text(to, 'And the first line of your address? (house number and street)');
      break;
    }
    case 'address': {
      if (input.kind !== 'text' || input.text.length < 4) {
        reply = text(to, 'Please type your house number and street name.'); break;
      }
      s.data.address = clip(input.text, 120);
      s.step = 'details';
      reply = text(to, 'Nearly done. In a sentence, what is happening? (for example: "boiler shows error F28 and radiators are cold")');
      break;
    }
    case 'details': {
      if (input.kind !== 'text' || input.text.length < 3) {
        reply = text(to, 'Please type a short description of the problem - it helps the engineer bring the right parts.'); break;
      }
      s.data.details = clip(input.text, 500);
      s.step = 'choice';
      reply = buttons(to, 'Thanks. How would you like us to help?\n\n1. Request a callback\n2. Book an engineer visit', CHOICES);
      break;
    }
    case 'choice': {
      let opt = pick(input, CHOICES);
      if (!opt && input.kind === 'text') {
        if (/call/.test(lower)) opt = CHOICES[0];
        else if (/visit|book|engineer/.test(lower)) opt = CHOICES[1];
      }
      if (!opt) { reply = buttons(to, 'Please tap one of the buttons, or reply 1 for a callback or 2 for a visit.', CHOICES); break; }
      s.data.choice = opt.id;
      if (opt.id === 'cb') {
        booking = finish(s, key);
        s.step = 'done';
        reply = text(to, 'All done, ' + clip(s.data.name.split(' ')[0], 30) + '. Your callback request is with the team and we will call you '
          + booking.slotLabel + '.\n\nYour reference: ' + s.ref);
      } else {
        s.dayOptions = nextWorkingDays(now, 3);
        s.step = 'day';
        reply = list(to, 'Which day suits you? Tap *Choose day*, or reply with a number:\n' + numbered(s.dayOptions),
          'Choose day', 'Next available days', s.dayOptions);
      }
      break;
    }
    case 'day': {
      const opts = Array.isArray(s.dayOptions) && s.dayOptions.length ? s.dayOptions : nextWorkingDays(now, 3);
      const opt = pick(input, opts);
      if (!opt) {
        s.dayOptions = opts;
        reply = list(to, 'Please pick one of these days (tap the button or reply with a number):\n' + numbered(opts),
          'Choose day', 'Next available days', opts);
        break;
      }
      s.data.day = opt.id; s.data.dayLabel = opt.title;
      s.step = 'window';
      reply = buttons(to, 'And what time on ' + opt.title + '?\n\n' + numbered(WINDOWS), WINDOWS);
      break;
    }
    case 'window': {
      let opt = pick(input, WINDOWS);
      if (!opt && input.kind === 'text') {
        if (/morning|\bam\b/.test(lower)) opt = WINDOWS[0];
        else if (/afternoon|\bpm\b/.test(lower)) opt = WINDOWS[1];
        else if (/evening/.test(lower)) opt = WINDOWS[2];
      }
      if (!opt) { reply = buttons(to, 'Please tap a time window, or reply 1, 2 or 3.\n\n' + numbered(WINDOWS), WINDOWS); break; }
      s.data.window = opt.id;
      booking = finish(s, key);
      s.step = 'done';
      reply = text(to, 'All done, ' + clip(s.data.name.split(' ')[0], 30) + '. We have your visit request for ' + booking.slotLabel
        + ' at ' + s.data.address + ', ' + s.data.postcode + '.\n\nWe will message you shortly to confirm your engineer.\n\nYour reference: ' + s.ref);
      break;
    }
    case 'done':
    default: {
      s.step = 'done';
      reply = text(to, 'You are all set - your reference is ' + s.ref + ' and the team has your details.\n\nNeed something else? Reply MENU to start a new request.');
      break;
    }
  }
  s.updated = nowMs;
  return { to, reply, booking, step: s.step };
}

// ---------- run ----------
const out = [];
for (const msg of messages) {
  if (!msg || !msg.from) continue;
  if (msg.id) {
    if (store.seen.includes(msg.id)) continue; // Meta retried the same webhook
    store.seen.push(msg.id);
  }
  const r = handle(msg);
  if (!r) continue;
  out.push({
    json: {
      to: r.to,
      step: r.step,
      graphVersion: cfg.graphVersion,
      phoneNumberId,
      waPayload: r.reply,
      bookingComplete: !!r.booking,
      booking: r.booking,
      ownerMobile: cfg.ownerMobile,
      twilioFrom: cfg.twilioFrom,
      calendarId: cfg.calendarId,
    },
  });
}
if (store.seen.length > 300) store.seen = store.seen.slice(-300);
store.lastRun = nowMs; // top-level write guarantees n8n saves the static data
return out;
